import logging
from taf.gnb.oam.ne3s.ws.components.PM.v1.PM import PMv1


log = logging.getLogger("taf.gnb.oam.ne3s.ws.logger")


class PmReportingNotActive(Exception):
    pass


class PMv2(PMv1):

    def __init__(self, connection):
        super(PMv2, self).__init__(connection)

    def prepare_params_for_pm_measurement(self, _, reporting_interval):
        pm_measurement_params = {'reportingIntervalPm': reporting_interval}
        return pm_measurement_params
